    /**
     * Method to retrieve the Bank via BankFetchOneSummary
     * @param 	summary BankFetchOneSummary 
     * @return 	BankFetchOneResponse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    public Bank getBank( BankFetchOneSummary summary ) 
    throws ProcessingException, IllegalArgumentException {
    	
    	if( summary == null )
    		throw new IllegalArgumentException( "BankFetchOneSummary arg cannot be null" );
    	
    	Bank entity = null;
    	
        try {
        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	BankValidator.getInstance().validate( summary );    
        	
        	// --------------------------------------
        	// use queryGateway to send request to Find a Bank
        	// --------------------------------------
        	CompletableFuture<Bank> futureEntity = queryGateway.query(new FindBankQuery( new LoadBankFilter( summary.getBankId() ) ), ResponseTypes.instanceOf(Bank.class));
        	
        	entity = futureEntity.get();
        }
        catch( Exception exc ) {
            final String errMsg = "Unable to locate Bank with id " + summary.getBankId();
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }


